--104 CR06. Additive canonical correction evidence; no financial seeds/backfill.
do $$declare d text;begin d:=pg_get_functiondef('private.customer_plan(uuid,text,jsonb)'::regprocedure);d:=replace(d,'select kind=''CLOSE''from public.construction_events','select ce.kind=''CLOSE''from public.construction_events ce');d:=replace(d,'and kind in(''CLOSE'',''REOPEN'')','and ce.kind in(''CLOSE'',''REOPEN'')');execute d;end$$;
create table public.commercial_reversals(
 id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),document_id uuid not null,date date not null,
 journal_id uuid not null,request_id uuid not null,request_hash text not null,evidence text not null,actor uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(company_id,document_id),unique(company_id,request_id),foreign key(company_id,document_id)references public.commercial_documents(company_id,id),foreign key(company_id,journal_id)references public.journal_entries(company_id,id));
alter table public.commercial_reversals enable row level security;alter table public.commercial_reversals force row level security;
revoke all on public.commercial_reversals from public,anon,authenticated,service_role;grant select on public.commercial_reversals to authenticated;
create policy commercial_reversal_read on public.commercial_reversals for select to authenticated using(public.has_company_role(company_id,'ACCOUNTING_ADMIN')or public.has_company_role(company_id,'ACCOUNTANT')or public.has_company_role(company_id,'MANAGEMENT_VIEWER'));
create trigger commercial_reversal_immutable before update or delete on public.commercial_reversals for each row execute function private.financial_evidence_immutable();
create function private.commercial_live(cid uuid,did uuid,cutoff date default 'infinity')returns boolean language sql stable set search_path=''as $$select not exists(select 1 from public.commercial_reversals r where r.company_id=cid and r.document_id=did and r.date<=cutoff)$$;
-- Preserve normalization and extend only new business identifiers.
do $$declare d text;begin d:=pg_get_functiondef('private.normalize_commercial_input(jsonb)'::regprocedure);if position('''party_id'',''project_id'',''treasury_id'',''parent_id'',''related_id'''in d)=0 then raise exception 'Unexpected normalizer';end if;d:=replace(d,'''party_id'',''project_id'',''treasury_id'',''parent_id'',''related_id''','''party_id'',''project_id'',''treasury_id'',''parent_id'',''related_id'',''source_expense_id'',''target_treasury_id'',''corrects_id'',''ar_document_id'',''asset_id''');execute d;end$$;
alter function private.recognition_plan(uuid,text,jsonb)rename to recognition_plan_pre104;
do $$declare d text;begin d:=pg_get_functiondef('private.recognition_plan_pre104(uuid,text,jsonb)'::regprocedure);if position('due<date_trunc(''month'',d)::date'in d)=0 then raise exception 'Unexpected disposal convention';end if;
 d:=replace(d,'due<date_trunc(''month'',d)::date','due<=d');
 d:=replace(d,'where company_id=cid and parent_id=parent.id','where company_id=cid and private.commercial_live(cid,id)and parent_id=parent.id');execute d;end$$;
create function private.recognition_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare n bigint;d date;src public.expenses;l public.journal_lines;p public.commercial_documents;a uuid;b uuid;t public.treasury_accounts;u public.treasury_accounts;lines jsonb;months integer;residual bigint;old uuid;begin
 if nullif(v->>'corrects_id','')is not null then
 select *into p from public.commercial_documents where company_id=cid and id=(v->>'corrects_id')::uuid;
 if p.id is null or p.kind<>kind or private.commercial_live(cid,p.id)or kind not in('ASSET_CAPITALIZE','ACCRUAL_RECOGNIZE','PREPAY_RECOGNIZE','TREASURY_TRANSFER')then raise exception 'Reversed original of same business kind required for corrected replacement'using errcode='23514';end if;end if;
 if nullif(v->>'parent_id','')is not null and not private.commercial_live(cid,(v->>'parent_id')::uuid)then raise exception 'Original document is reversed'using errcode='23514';end if;
 if kind='TREASURY_TRANSFER'or(kind='ASSET_CAPITALIZE'and nullif(v->>'source_expense_id','')is not null)then
 if jsonb_typeof(v)is distinct from 'object'or v-array['date','reference','evidence','amount_minor','project_id','treasury_id','target_treasury_id','source_expense_id','life_months','residual_minor','service_date','convention','corrects_id']<>'{}'::jsonb or coalesce(length(v->>'reference'),0)not between 1 and 120 or coalesce(length(v->>'evidence'),0)not between 5 and 1000 or coalesce(v->>'amount_minor','')!~'^[0-9]{1,16}$'or(v->>'amount_minor')::numeric not between 1 and 9000000000000000 or coalesce(v->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(v->>'date')::date>current_date then raise exception 'Exact dated business amount, reference and evidence required'using errcode='23514';end if;
 n:=(v->>'amount_minor')::bigint;d:=(v->>'date')::date;perform private.opening_period(cid,d);
 if kind='TREASURY_TRANSFER'then
 if v-array['date','reference','evidence','amount_minor','treasury_id','target_treasury_id','corrects_id']<>'{}'::jsonb then raise exception 'Transfer accepts actual money locations only'using errcode='22023';end if;
 select *into t from public.treasury_accounts where company_id=cid and id=(v->>'treasury_id')::uuid;select *into u from public.treasury_accounts where company_id=cid and id=(v->>'target_treasury_id')::uuid;
 if t.id is null or u.id is null or t.id=u.id or t.gl_account_id=u.gl_account_id then raise exception 'Two distinct same-Company real Treasury locations required'using errcode='23514';end if;
 a:=private.commercial_bank(cid,t.id,d,n,true);b:=private.commercial_bank(cid,u.id,d,n,false);lines:=jsonb_build_array(private.commercial_line(b,n,false,null,u.project_id,u.id),private.commercial_line(a,n,true,null,t.project_id,t.id));
 else
 if v?'treasury_id'or v?'target_treasury_id'then raise exception 'Source capitalization cannot create another payment'using errcode='23514';end if;
 select *into src from public.expenses where company_id=cid and id=(v->>'source_expense_id')::uuid;
 select x.*into l from public.journal_lines x join public.accounts ac on ac.company_id=x.company_id and ac.id=x.account_id where x.company_id=cid and x.journal_entry_id=src.posted_journal_entry_id and ac.account_type='EXPENSE'and x.debit_minor>0 and x.credit_minor=0;
 if src.id is null or src.status<>'POSTED'or src.expense_date>d or exists(select 1 from public.supplier_ap_documents ac where ac.company_id=cid and ac.expense_id=src.id and ac.kind='CREDIT_NOTE'and ac.status='POSTED'and ac.posting_date>d)or l.id is null or n<>l.debit_minor-private.source_credit_total(cid,src.id)or l.project_id is distinct from nullif(v->>'project_id','')::uuid or(select count(*)from public.journal_lines x join public.accounts ac on ac.company_id=x.company_id and ac.id=x.account_id where x.company_id=cid and x.journal_entry_id=src.posted_journal_entry_id and ac.account_type='EXPENSE')<>1 or exists(select 1 from public.journal_entries where company_id=cid and reversal_of_journal_entry_id=src.posted_journal_entry_id)then raise exception 'Unreversed exact single-cost Company invoice/Expense and its Project required'using errcode='23514';end if;
 if exists(select 1 from public.commercial_documents where company_id=cid and commercial_documents.kind='ASSET_CAPITALIZE'and input->>'source_expense_id'=src.id::text and private.commercial_live(cid,id))or exists(select 1 from public.commercial_documents where company_id=cid and kind='CR_WIP_CAPITALIZE'and input->>'source_line_id'=l.id::text and private.construction_live(cid,id))or exists(select 1 from public.inventory_events i where i.company_id=cid and i.state='POSTED'and i.snapshot->>'expense_id'=src.id::text and i.snapshot->>'kind'in('RECEIPT','MATCH','INVOICE')and not exists(select 1 from public.inventory_events r where r.company_id=cid and r.document_id=i.document_id and r.state='REVERSED'))or exists(select 1 from public.project_cost_corrections where company_id=cid and expense_id=src.id)or exists(select 1 from public.source_reclassification_events where company_id=cid and state='POSTED'and(origin->>'id'=src.id::text or replacement->>'id'=src.id::text))then raise exception 'Source already allocated/corrected; no duplicate asset, WIP or Inventory recognition'using errcode='23514';end if;
 months:=(v->>'life_months')::integer;residual:=coalesce((v->>'residual_minor')::bigint,0);
 if months is null or months not between 1 and 1200 or residual<0 or residual>=n or coalesce(v->>'service_date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(v->>'service_date')::date<d or v->>'convention'is distinct from 'COMPLETED_MONTHS'then raise exception 'Supported life, service date, residual and completed-month convention required'using errcode='23514';end if;
 lines:=jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ASSET_COST'),n,false,null,l.project_id),private.commercial_line(l.account_id,n,true,l.party_id,l.project_id)||jsonb_build_object('subcontract_id',l.subcontract_id));end if;
 return jsonb_build_object('lines',lines,'amount',n);
 end if;
 return private.recognition_plan_pre104(cid,kind,v-'corrects_id');end$$;
-- Typed reversals reuse the immutable journal kernel; no arbitrary financial lines.
create function public.preview_commercial_reversal(cid uuid,document uuid,date date,evidence text)returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare p public.commercial_documents;l record;begin
 perform private.operational_finance_actor(cid,'accounting.reverse');if not public.has_company_role(cid,'ACCOUNTING_ADMIN')then raise exception 'Accounting Admin correction approval required'using errcode='42501';end if;perform private.serialize_operational_finance(cid,'OPERATIONS');
 select *into p from public.commercial_documents where company_id=cid and id=document for update;
 if p.id is null or p.kind not in('ASSET_CAPITALIZE','ASSET_DEPRECIATE','ASSET_DISPOSE','ACCRUAL_RECOGNIZE','ACCRUAL_SETTLE','PREPAY_RECOGNIZE','PREPAY_AMORTIZE','TREASURY_TRANSFER')or not private.commercial_live(cid,p.id)or date is null or date<p.date or date>current_date or coalesce(length(btrim(evidence)),0)not between 5 and 1000 then raise exception 'Live supported document, actual correction date and reason required'using errcode='23514';end if;
 perform private.opening_period(cid,date);
 if exists(select 1 from public.commercial_documents where company_id=cid and parent_id=p.id and private.commercial_live(cid,id))then raise exception 'Reverse later depreciation/amortization/disposal/settlement dependencies first'using errcode='23514';end if;
 if p.kind in('ASSET_DEPRECIATE','PREPAY_AMORTIZE')and exists(select 1 from public.commercial_documents where company_id=cid and parent_id=p.parent_id and private.commercial_live(cid,id)and(commercial_documents.date>p.date or commercial_documents.kind='ASSET_DISPOSE'))then raise exception 'Reverse later schedule installments first'using errcode='23514';end if;
 for l in select treasury_account_id,sum(debit_minor-credit_minor)n from public.journal_lines where company_id=cid and journal_entry_id=p.journal_id and treasury_account_id is not null group by treasury_account_id having sum(debit_minor-credit_minor)>0 loop perform private.commercial_bank(cid,l.treasury_account_id,date,l.n::bigint,true);end loop;
 return jsonb_build_object('id',p.id,'lines',(select jsonb_agg(jsonb_build_object('account_id',x.account_id,'code',a.code,'name',a.name,'debit_minor',x.credit_minor::text,'credit_minor',x.debit_minor::text,'project_id',x.project_id,'party_id',x.party_id,'treasury_account_id',x.treasury_account_id)order by x.line_number)from public.journal_lines x join public.accounts a on a.company_id=x.company_id and a.id=x.account_id where x.company_id=cid and x.journal_entry_id=p.journal_id));end$$;
create function public.reverse_commercial_document(cid uuid,request_id uuid,document uuid,date date,evidence text)returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare actor uuid;r public.commercial_reversals;h text;p public.commercial_documents;j uuid;q private.financial_command_requests;begin
 actor:=private.operational_finance_actor(cid,'accounting.reverse');if request_id is null then raise exception 'Request identity required'using errcode='22023';end if;perform private.serialize_operational_finance(cid,'OPERATIONS');h:=encode(extensions.digest(jsonb_build_array(actor,document,date,btrim(evidence))::text,'sha256'),'hex');select *into r from public.commercial_reversals where company_id=cid and commercial_reversals.request_id=reverse_commercial_document.request_id;
 if r.id is not null then if r.request_hash<>h then raise exception 'Changed reversal request'using errcode='23505';end if;return jsonb_build_object('id',r.id,'journal_id',r.journal_id,'replayed',true);end if;
 perform public.preview_commercial_reversal(cid,document,date,evidence);select *into p from public.commercial_documents where company_id=cid and id=document;
 q:=private.reserve_financial_command(cid,'COMMERCIAL_REVERSAL',request_id,h,actor);j:=private.reverse_journal(p.journal_id,date,btrim(evidence),actor);
 insert into public.commercial_reversals(company_id,document_id,date,journal_id,request_id,request_hash,evidence,actor)values(cid,document,date,j,request_id,h,btrim(evidence),actor)returning *into r;perform private.complete_financial_command(q.id,j);return jsonb_build_object('id',r.id,'journal_id',j);end$$;
create or replace function public.read_period_recognition(cid uuid,as_of date)returns jsonb language plpgsql stable security definer set search_path=''as $$begin
 if auth.uid()is null or not(public.has_company_role(cid,'ACCOUNTING_ADMIN')or public.has_company_role(cid,'ACCOUNTANT')or public.has_company_role(cid,'MANAGEMENT_VIEWER'))then raise exception 'Recognition access denied'using errcode='42501';end if;if as_of is null then raise exception 'Cutoff required'using errcode='22023';end if;
 return jsonb_build_object('documents',(select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('amount_minor',x.amount_minor::text,'effective',private.commercial_live(cid,x.id,as_of),'remaining_minor',(case when not private.commercial_live(cid,x.id,as_of)or(x.kind='ASSET_CAPITALIZE'and exists(select 1 from public.commercial_documents y where y.company_id=cid and y.parent_id=x.id and y.kind='ASSET_DISPOSE'and y.date<=as_of and private.commercial_live(cid,y.id,as_of)))then 0 else x.amount_minor-coalesce((select sum(y.amount_minor)from public.commercial_documents y where y.company_id=cid and y.parent_id=x.id and y.date<=as_of and private.commercial_live(cid,y.id,as_of)),0)end)::text)order by x.date,x.id),'[]')from public.commercial_documents x where x.company_id=cid and x.date<=as_of and(x.kind like 'ASSET_%'or x.kind like 'ACCRUAL_%'or x.kind like 'PREPAY_%'or x.kind='TREASURY_TRANSFER')),'reversals',(select coalesce(jsonb_agg(to_jsonb(r)),'[]')from public.commercial_reversals r where company_id=cid and date<=as_of));end$$;
-- Explicit tax-point deposits. Amounts are NET liability; actual cash includes tax.
-- Original tax documents/rates and proportional final remainders govern relief/refund.
alter function private.customer_plan_pre103(uuid,text,jsonb)rename to customer_plan_legacy104;
do $$declare d text;begin d:=pg_get_functiondef('private.customer_plan_legacy104(uuid,text,jsonb)'::regprocedure);
 d:=replace(d,'s.company_id=cid and s.parent_id=parent.id','s.company_id=cid and private.construction_live(cid,s.id)and s.parent_id=parent.id');
 d:=replace(d,'s.company_id=cid and(s.related_id=adv.id or s.parent_id=adv.id)','s.company_id=cid and private.construction_live(cid,s.id)and(s.related_id=adv.id or s.parent_id=adv.id)');execute d;end$$;
create function private.customer_plan_pre103(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare adv public.commercial_documents;invoice public.commercial_documents;n bigint;tax bigint;used bigint;prior_tax bigint;relief bigint;bank uuid;project uuid;lines jsonb;original_tax bigint;rate integer;begin
 if kind in('AR_APPLY','AR_REFUND')then select *into adv from public.commercial_documents where company_id=cid and id=(case when kind='AR_APPLY'then v->>'related_id'else v->>'parent_id'end)::uuid;end if;
 if(kind='AR_ADVANCE'and coalesce((v->>'vat_minor')::bigint,0)>0)or(adv.kind='AR_ADVANCE'and coalesce((adv.input->>'vat_minor')::bigint,0)>0)then
 if v-array['date','party_id','project_id','treasury_id','parent_id','related_id','reference','amount_minor','vat_minor','vat_rate_bps','tax_evidence','evidence']<>'{}'::jsonb or coalesce(v->>'amount_minor','')!~'^[0-9]{1,16}$'or(v->>'amount_minor')::numeric not between 1 and 9000000000000000 or coalesce(v->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(v->>'date')::date>current_date or coalesce(length(v->>'reference'),0)not between 1 and 120 or coalesce(length(v->>'evidence'),0)not between 5 and 1000 or coalesce(length(v->>'tax_evidence'),0)not between 5 and 1000 then raise exception 'Documented deposit tax point/adjustment, exact amount/date and evidence required'using errcode='23514';end if;
 n:=(v->>'amount_minor')::bigint;project:=nullif(v->>'project_id','')::uuid;perform private.opening_period(cid,(v->>'date')::date);
 if not exists(select 1 from public.customer_accounts where company_id=cid and party_id=(v->>'party_id')::uuid)or project is not null and not exists(select 1 from public.projects where company_id=cid and id=project)then raise exception 'Same-Company Customer and Project required'using errcode='23514';end if;
 if kind='AR_ADVANCE'then
 tax:=(v->>'vat_minor')::bigint;rate:=(v->>'vat_rate_bps')::integer;
 if v?'parent_id'or v?'related_id'or not exists(select 1 from public.parties where company_id=cid and id=(v->>'party_id')::uuid and status='ACTIVE')or rate is null or rate not between 1 and 10000 or tax<>round(n::numeric*rate/10000)or n::numeric+tax>9000000000000000 then raise exception 'Active Customer and exact evidenced deposit tax rate/amount required'using errcode='23514';end if;
 bank:=private.commercial_bank(cid,(v->>'treasury_id')::uuid,(v->>'date')::date,n+tax,false);
 lines:=jsonb_build_array(private.commercial_line(bank,n+tax,false,null,project,(v->>'treasury_id')::uuid),private.commercial_line(private.commercial_account(cid,'CUSTOMER_ADVANCE'),n,true,(v->>'party_id')::uuid),private.commercial_line(private.commercial_account(cid,'OUTPUT_VAT'),tax,true));
 return jsonb_build_object('amount',n,'ar_reduction',0,'customer_credit',0,'lines',lines,'advance_vat_minor',tax::text);
 end if;
 if adv.id is null or adv.party_id is distinct from(v->>'party_id')::uuid or adv.date>(v->>'date')::date or not private.construction_live(cid,adv.id)or coalesce((v->>'vat_minor')::bigint,0)<>0 then raise exception 'Original available same-Customer deposit and no invented tax required'using errcode='23514';end if;
 select coalesce(sum(amount_minor),0),coalesce(sum((input->>'advance_vat_minor')::bigint),0)into used,prior_tax from public.commercial_documents where company_id=cid and private.construction_live(cid,id)and(related_id=adv.id or parent_id=adv.id);
 if n>adv.amount_minor-used then raise exception 'Deposit allocation/refund exceeds remaining NET liability'using errcode='23514';end if;original_tax:=(adv.input->>'vat_minor')::bigint;rate:=(adv.input->>'vat_rate_bps')::integer;
 relief:=case when n=adv.amount_minor-used then original_tax-prior_tax else least(original_tax-prior_tax,round(n::numeric*rate/10000)::bigint)end;
 if kind='AR_APPLY'then
 if adv.project_id is not null and adv.project_id is distinct from project then raise exception 'Deposit Project cannot fund an unrelated Project'using errcode='23514';end if;if v?'treasury_id'then raise exception 'Allocation cannot move cash'using errcode='23514';end if;
 select *into invoice from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid;
 if invoice.id is null or invoice.kind<>'AR_INVOICE'or invoice.party_id<>adv.party_id or invoice.project_id is distinct from project or invoice.date>(v->>'date')::date or not private.construction_live(cid,invoice.id)or coalesce((invoice.input->>'vat_rate_bps')::integer,0)<>rate or n+relief>invoice.amount_minor-coalesce((select sum(ar_reduction_minor)from public.commercial_documents where company_id=cid and parent_id=invoice.id and private.construction_live(cid,id)),0)then raise exception 'Supported same-tax-rate invoice and sufficient gross receivable required'using errcode='23514';end if;
 lines:=jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CUSTOMER_ADVANCE'),n,false,adv.party_id),private.commercial_line(private.commercial_account(cid,'AR'),n+relief,true,adv.party_id,project));
 else
 if v?'related_id'or project is not null then raise exception 'Actual original deposit refund required'using errcode='23514';end if;
 bank:=private.commercial_bank(cid,(v->>'treasury_id')::uuid,(v->>'date')::date,n+relief,true);lines:=jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CUSTOMER_ADVANCE'),n,false,adv.party_id),private.commercial_line(bank,n+relief,true,null,project,(v->>'treasury_id')::uuid));end if;
 if relief>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'OUTPUT_VAT'),relief,false));end if;
 return jsonb_build_object('amount',n,'customer_credit',0,'lines',lines,'ar_reduction',case when kind='AR_APPLY'then n+relief else 0 end,'advance_vat_minor',relief::text);
 end if;
 if nullif(v->>'parent_id','')is not null and not private.construction_live(cid,(v->>'parent_id')::uuid)or nullif(v->>'related_id','')is not null and not private.construction_live(cid,(v->>'related_id')::uuid)then raise exception 'Original customer document is reversed'using errcode='23514';end if;
 return private.customer_plan_legacy104(cid,kind,v);end$$;
-- Freeze derived tax relief with the existing canonical AR document, never caller journal lines.
do $$declare d text;begin d:=pg_get_functiondef('public.command_customer_accounting(uuid,uuid,text,jsonb)'::regprocedure);
 if position(',input,request_id,h,actor)'in d)=0 then raise exception 'Unexpected AR command snapshot definition';end if;
 d:=replace(d,',input,request_id,h,actor)',',input||jsonb_build_object(''advance_vat_minor'',coalesce(plan->>''advance_vat_minor'',''0'')),request_id,h,actor)');execute d;end$$;
-- Preserve a single recognized asset/cost across existing source correction routes.
create function private.protect_allocated_cost_source()returns trigger language plpgsql security definer set search_path=''as $$declare expense uuid;line uuid;begin
 if tg_table_name='journal_entries'then select id into expense from public.expenses where company_id=new.company_id and posted_journal_entry_id=new.reversal_of_journal_entry_id;
 elsif tg_table_name='inventory_events'then if new.state<>'POSTED'or new.snapshot->>'kind'not in('RECEIPT','MATCH','INVOICE')then return new;end if;expense:=nullif(new.snapshot->>'expense_id','')::uuid;
 else expense:=new.expense_id;end if;
 if expense is not null and(exists(select 1 from public.commercial_documents where company_id=new.company_id and kind='ASSET_CAPITALIZE'and input->>'source_expense_id'=expense::text and private.commercial_live(new.company_id,id))or(tg_table_name='project_cost_corrections'and exists(select 1 from public.commercial_documents d join public.journal_lines l on l.company_id=d.company_id and l.id=(d.input->>'source_line_id')::uuid join public.expenses e on e.company_id=l.company_id and e.posted_journal_entry_id=l.journal_entry_id where d.company_id=new.company_id and e.id=expense and d.kind='CR_WIP_CAPITALIZE'and private.construction_live(new.company_id,d.id))))then raise exception 'Reverse dependent asset/WIP allocation before changing its original cost source'using errcode='23514';end if;return new;end$$;
create trigger asset_source_reversal before insert on public.journal_entries for each row when(new.reversal_of_journal_entry_id is not null)execute function private.protect_allocated_cost_source();
create trigger asset_source_stock before insert on public.inventory_events for each row execute function private.protect_allocated_cost_source();
create trigger allocated_cost_correction before insert on public.project_cost_corrections for each row execute function private.protect_allocated_cost_source();
-- The Treasury location remains real cash even when its analytic Project has closed.
do $$declare d text;begin d:=pg_get_functiondef('private.guard_closed_project_journal()'::regprocedure);if position('''AR_REFUND'')'in d)=0 then raise exception 'Unexpected closed Project settlement guard';end if;d:=replace(d,'''AR_REFUND'')','''AR_REFUND'',''TREASURY_TRANSFER'')');execute d;end$$;
revoke all on function private.commercial_live(uuid,uuid,date),private.recognition_plan_pre104(uuid,text,jsonb),private.recognition_plan(uuid,text,jsonb),private.customer_plan_legacy104(uuid,text,jsonb),private.customer_plan_pre103(uuid,text,jsonb),private.protect_allocated_cost_source(),public.preview_commercial_reversal(uuid,uuid,date,text),public.reverse_commercial_document(uuid,uuid,uuid,date,text)from public,anon,authenticated,service_role;
grant execute on function public.preview_commercial_reversal(uuid,uuid,date,text),public.reverse_commercial_document(uuid,uuid,uuid,date,text)to authenticated;
-- Construction credits adjust unconditional billing independently from earned revenue.
alter function private.construction_plan(uuid,text,jsonb)rename to construction_plan_pre104;
do $$declare d text;begin d:=pg_get_functiondef('private.construction_plan_pre104(uuid,text,jsonb)'::regprocedure);
 d:=replace(d,'if n<1 or tax<>0 then','if n<1 or(action<>''ADVANCE''and tax<>0)then');
 d:=replace(d,'if action=''ADVANCE''and v->>''tax_confirmed''','if action=''ADVANCE''and tax=0 and v->>''tax_confirmed''');
 d:=replace(d,'''vat_minor'',''0'',''reference'',v->>''reference''','''vat_minor'',case when action=''ADVANCE''then tax::text else ''0''end,''reference'',v->>''reference''');
 d:=replace(d,'lines:=(private.customer_plan(cid,''AR_''||','if action=''ADVANCE''and tax>0 then p:=p||jsonb_build_object(''vat_rate_bps'',v->''vat_rate_bps'',''tax_evidence'',v->>''tax_evidence'');elsif action in(''APPLY'',''REFUND'')and nullif(v->>''tax_evidence'','''')is not null then p:=p||jsonb_build_object(''tax_evidence'',v->>''tax_evidence'');end if;lines:=(private.customer_plan(cid,''AR_''||');execute d;end$$;
create function private.construction_plan(cid uuid,action text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare c public.construction_contracts;p public.commercial_documents;b jsonb;n bigint;tax bigint;ret bigint;used bigint;available bigint;credit bigint;bill bigint;position bigint;portion bigint;remaining_net bigint;remaining_tax bigint;lines jsonb:='[]';begin
 if action not in('CREDIT_BILL','REDUCE_REVENUE')then
 if action='REVERSE'then select *into p from public.commercial_documents where company_id=cid and id=(v->>'id')::uuid;if p.kind not in('AR_CREDIT','CR_REVENUE_CREDIT')then return private.construction_plan_pre104(cid,action,v);end if;
 else return private.construction_plan_pre104(cid,action,v);end if;end if;
 perform private.operational_finance_actor(cid,case when action='REVERSE'then 'accounting.reverse'else 'accounting.post'end);if not public.has_company_role(cid,'ACCOUNTING_ADMIN')then raise exception 'Accounting Admin credit/correction approval required'using errcode='42501';end if;perform private.attendance_company_lock(cid);perform private.serialize_operational_finance(cid,'OPERATIONS');
 if v-array['contract_id','date','reference','evidence','amount_minor','vat_minor','retention_minor','parent_id','id','recognition_confirmed','tax_evidence']<>'{}'::jsonb or coalesce(length(v->>'reference'),0)not between 1 and 120 or coalesce(length(v->>'evidence'),0)not between 5 and 1000 or coalesce(v->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(v->>'date')::date>current_date then raise exception 'Bounded original-linked credit/correction evidence required'using errcode='23514';end if;
 perform private.opening_period(cid,(v->>'date')::date);select *into c from public.construction_contracts where company_id=cid and id=(v->>'contract_id')::uuid for update;
 if c.id is null then raise exception 'Same-Company contract required'using errcode='42501';end if;if coalesce((select ce.kind='CLOSE'from public.construction_events ce where ce.company_id=cid and ce.contract_id=c.id and ce.kind in('CLOSE','REOPEN')order by ce.created_at desc,ce.id desc limit 1),false)then raise exception 'Reopen contract with audited approval before billing/revenue corrections'using errcode='23514';end if;
 if(v->>'date')::date<greatest(c.from_date,(select max(date)from public.construction_events where company_id=cid and contract_id=c.id),(select max(date)from private.construction_docs(cid,c.id)))then raise exception 'Chronological correction date required'using errcode='23514';end if;
 select *into p from private.construction_docs(cid,c.id)where id=(case when action='REVERSE'then v->>'id'else v->>'parent_id'end)::uuid;
 if p.id is null or p.date>(v->>'date')::date then raise exception 'Live original contract document required'using errcode='23514';end if;
 if action='REVERSE'then
 if p.id is distinct from(select d.id from private.construction_docs(cid,c.id)d where d.kind like 'CR_%'or d.kind in('AR_INVOICE','AR_CREDIT')order by d.created_at desc,d.id desc limit 1)or exists(select 1 from public.commercial_documents d where d.company_id=cid and(d.parent_id=p.id or d.related_id=p.id)and private.construction_live(cid,d.id))then raise exception 'Reverse later correction/credit allocation/refund dependencies first'using errcode='23514';end if;
 select jsonb_agg(jsonb_build_object('account_id',l.account_id,'project_id',l.project_id,'party_id',l.party_id,'treasury_account_id',l.treasury_account_id,'debit_minor',l.credit_minor::text,'credit_minor',l.debit_minor::text)order by l.line_number)into lines from public.journal_lines l where l.company_id=cid and l.journal_entry_id=p.journal_id;
 return v||jsonb_build_object('lines',lines);end if;
 if coalesce(v->>'amount_minor','')!~'^[0-9]{1,16}$'or(v->>'amount_minor')::numeric not between 1 and 9000000000000000 then raise exception 'Positive exact correction amount required'using errcode='23514';end if;
 n:=(v->>'amount_minor')::bigint;tax:=coalesce((v->>'vat_minor')::bigint,0);ret:=coalesce((v->>'retention_minor')::bigint,0);b:=private.construction_balance(cid,c.id);position:=(b->>'net_position')::bigint;
 if action='CREDIT_BILL'then
 if p.kind<>'AR_INVOICE'or p.input->>'construction_action'<>'BILL'then raise exception 'Original progress invoice required'using errcode='23514';end if;
 select(p.input->>'amount_minor')::bigint-coalesce(sum((d.input->>'amount_minor')::bigint),0),(p.input->>'vat_minor')::bigint-coalesce(sum((d.input->>'vat_minor')::bigint),0)into remaining_net,remaining_tax from private.construction_docs(cid,c.id)d where d.parent_id=p.id and d.input->>'construction_action'='CREDIT_BILL';
 if n>remaining_net or tax<>(case when n=remaining_net then remaining_tax else round(n::numeric*coalesce((p.input->>'vat_rate_bps')::integer,0)/10000)end)or ret<0 or ret>least(n,(b->>'retention')::bigint,coalesce((p.input->>'retention_minor')::bigint,0)-coalesce((select sum((d.input->>'retention_minor')::bigint)from private.construction_docs(cid,c.id)d where d.parent_id=p.id and d.input->>'construction_action'='CREDIT_BILL'),0))or(tax>0 and coalesce(length(v->>'tax_evidence'),0)<5)then raise exception 'Credit must match original remaining net/tax and actual unreleased retention rights'using errcode='23514';end if;
 available:=p.amount_minor-coalesce((select sum(d.ar_reduction_minor)from public.commercial_documents d where d.company_id=cid and d.parent_id=p.id and private.construction_live(cid,d.id)),0);
 credit:=n+tax-ret;if credit<1 then raise exception 'Positive Customer credit amount required'using errcode='23514';end if;used:=least(available,credit);bill:=n-case when c.retention_basis='CONDITIONAL'then ret else 0 end;portion:=least(greatest(-position,0),bill);
 if portion>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CONTRACT_LIABILITY'),portion,false,c.customer_id,c.project_id));end if;
 if bill>portion then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CONTRACT_ASSET'),bill-portion,false,c.customer_id,c.project_id));end if;
 if tax>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'OUTPUT_VAT'),tax,false,null,c.project_id));end if;
 if ret>0 and c.retention_basis='UNCONDITIONAL'then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CUSTOMER_RETENTION'),ret,true,c.customer_id,c.project_id));end if;
 if used>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'AR'),used,true,c.customer_id,c.project_id));end if;
 if credit>used then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CUSTOMER_ADVANCE'),credit-used,true,c.customer_id));end if;
 return v||jsonb_build_object('lines',lines,'bill_net_minor',(-bill)::text,'retention_minor',ret::text,'ar_amount_minor',credit::text,'ar_reduction_minor',used::text,'customer_credit_minor',(credit-used)::text);
 else
 if p.kind<>'CR_REVENUE'or tax<>0 or ret<>0 or v->>'recognition_confirmed'is distinct from 'true'or n>(b->>'revenue')::bigint or n>p.amount_minor-coalesce((select sum(d.amount_minor)from private.construction_docs(cid,c.id)d where d.parent_id=p.id and d.kind='CR_REVENUE_CREDIT'),0)then raise exception 'Explicit evidenced earned-revenue reduction bounded by original and current earnings required'using errcode='23514';end if;
 portion:=least(greatest(position,0),n);lines:=jsonb_build_array(private.commercial_line(private.commercial_account(cid,'REVENUE'),n,false,null,c.project_id));if portion>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CONTRACT_ASSET'),portion,true,c.customer_id,c.project_id));end if;if n>portion then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CONTRACT_LIABILITY'),n-portion,true,c.customer_id,c.project_id));end if;
 return v||jsonb_build_object('lines',lines);end if;end$$;
-- Reuse the same canonical construction posting command and atomic registry.
do $$declare d text;begin d:=pg_get_functiondef('public.command_construction(uuid,uuid,text,jsonb)'::regprocedure);
 if position('case action when ''BILL'''in d)=0 then raise exception 'Unexpected construction command';end if;
 d:=replace(d,'case action when ''BILL''','case action when ''CREDIT_BILL''then ''AR_CREDIT''when ''REDUCE_REVENUE''then ''CR_REVENUE_CREDIT''when ''BILL''');
 d:=replace(d,'journal_id,ar_reduction_minor,input,request_id','journal_id,ar_reduction_minor,customer_credit_minor,input,request_id');
 d:=replace(d,'when action in(''BILL'',''RELEASE_RETENTION'')','when action in(''BILL'',''RELEASE_RETENTION'',''CREDIT_BILL'')');
 d:=replace(d,'j,case when action=''REVERSE''and orig.kind=''AR_INVOICE''then orig.amount_minor else 0 end,snapshot','j,case when action=''CREDIT_BILL''then(plan->>''ar_reduction_minor'')::bigint when action=''REVERSE''and orig.kind=''AR_INVOICE''then orig.amount_minor else 0 end,case when action=''CREDIT_BILL''then(plan->>''customer_credit_minor'')::bigint else 0 end,snapshot');execute d;end$$;
create or replace function private.construction_balance(cid uuid,contract uuid,cutoff date default 'infinity')returns jsonb language sql stable set search_path=''as $$
 with docs as materialized(select *from private.construction_docs(cid,contract,cutoff)),v as(select
 coalesce(sum(case when kind='CR_REVENUE'then amount_minor when kind='CR_REVENUE_CREDIT'then -amount_minor else 0 end),0)rev,
 coalesce(sum((input->>'bill_net_minor')::bigint)filter(where kind in('AR_INVOICE','AR_CREDIT')and input->>'construction_action'in('BILL','RELEASE_RETENTION','CREDIT_BILL')),0)billed,
 coalesce(sum((input->>'retention_minor')::bigint)filter(where input->>'construction_action'='BILL'),0)-coalesce(sum(amount_minor)filter(where input->>'construction_action'='RELEASE_RETENTION'),0)-coalesce(sum((input->>'retention_minor')::bigint)filter(where input->>'construction_action'='CREDIT_BILL'),0)retention,
 coalesce(sum(amount_minor)filter(where kind in('CR_WIP_CAPITALIZE','CR_WIP_OPENING')),0)-coalesce(sum(amount_minor)filter(where kind in('CR_WIP_RELEASE','CR_WIP_IMPAIR')),0)wip,
 coalesce(sum(case when kind='AR_RECEIPT'then amount_minor when kind='AR_ADVANCE'then amount_minor+coalesce((input->>'vat_minor')::bigint,0)when kind='AR_REFUND'then -amount_minor-coalesce((input->>'advance_vat_minor')::bigint,0)else 0 end),0)collected,
 coalesce(sum(case when kind='AR_ADVANCE'then amount_minor when kind='AR_CREDIT'then customer_credit_minor when kind in('AR_APPLY','AR_REFUND')then -amount_minor else 0 end),0)advance from docs)
 select jsonb_build_object('revenue',rev::text,'billed',billed::text,'net_position',(rev-billed)::text,'retention',retention::text,'wip',wip::text,'collected',collected::text,'advance',advance::text)from v$$;
-- Derived active balances preserve original documents and show reversed rows with zero financial availability.
do $$declare d text;begin d:=pg_get_functiondef('public.read_customer_accounts(uuid,date)'::regprocedure);
 d:=replace(d,'where s.company_id=cid and s.parent_id=x.id','where s.company_id=cid and private.construction_live(cid,s.id,as_of)and s.parent_id=x.id');
 d:=replace(d,'where s.company_id=cid and s.date<=as_of','where s.company_id=cid and private.construction_live(cid,s.id,as_of)and s.date<=as_of');
 d:=replace(d,'''outstanding_minor'',case when x.kind=''AR_INVOICE''then','''effective'',private.construction_live(cid,x.id,as_of),''outstanding_minor'',case when not private.construction_live(cid,x.id,as_of)then ''0''when x.kind=''AR_INVOICE''then');execute d;end$$;
alter function public.read_customer_accounts(uuid,date)security definer;
revoke all on function private.construction_plan_pre104(uuid,text,jsonb),private.construction_plan(uuid,text,jsonb)from public,anon,authenticated,service_role;
-- Existing asset UI can select an authoritative AP/paid Expense cost instead of paying twice.
do $$declare d text;begin d:=pg_get_functiondef('public.read_commercial_workspace(uuid)'::regprocedure);
 if position('''years'','in d)=0 then raise exception 'Unexpected workspace reader';end if;
 d:=replace(d,'''years'',','''asset_sources'',coalesce((select jsonb_agg(jsonb_build_object(''id'',e.id,''reference'',e.expense_reference,''description'',e.description,''project_id'',l.project_id,''amount_minor'',(l.debit_minor-private.source_credit_total(cid,e.id))::text))from public.expenses e join public.journal_lines l on l.company_id=e.company_id and l.journal_entry_id=e.posted_journal_entry_id join public.accounts a on a.company_id=l.company_id and a.id=l.account_id where e.company_id=cid and e.status=''POSTED''and a.account_type=''EXPENSE''and l.debit_minor>private.source_credit_total(cid,e.id)and l.credit_minor=0 and not exists(select 1 from public.commercial_documents c where c.company_id=cid and c.kind=''ASSET_CAPITALIZE''and c.input->>''source_expense_id''=e.id::text and private.commercial_live(cid,c.id))and not exists(select 1 from public.journal_entries r where r.company_id=cid and r.reversal_of_journal_entry_id=e.posted_journal_entry_id)),''[]''::jsonb),''years'',');execute d;end$$;
alter function public.read_commercial_workspace(uuid)security definer;
-- Actual-day continuous service coverage supplements the existing discrete-month policy.
do $$declare d text;begin d:=pg_get_functiondef('private.normalize_commercial_input(jsonb)'::regprocedure);d:=replace(d,'''date'',''due_date'',''service_date''','''date'',''due_date'',''service_date'',''service_end_date''');execute d;end$$;
alter function private.recognition_plan(uuid,text,jsonb)rename to recognition_plan_core104;
create function private.recognition_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare p public.commercial_documents;n bigint;d date;start_day date;end_day date;last_day date;due date;used bigint;expected bigint;bank uuid;begin
 if kind='PREPAY_AMORTIZE'then select *into p from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid;end if;
 if(kind='PREPAY_RECOGNIZE'and v->>'convention'='ACTUAL_DAYS')or(kind='PREPAY_AMORTIZE'and p.input->>'convention'='ACTUAL_DAYS')then
 if v-array['date','reference','evidence','amount_minor','project_id','treasury_id','parent_id','service_date','service_end_date','convention','corrects_id']<>'{}'::jsonb or coalesce(v->>'date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(v->>'date')::date>current_date or coalesce(v->>'amount_minor','')!~'^[0-9]{1,16}$'or(v->>'amount_minor')::numeric not between 1 and 9000000000000000 or coalesce(length(v->>'reference'),0)not between 1 and 120 or coalesce(length(v->>'evidence'),0)not between 5 and 1000 then raise exception 'Supported actual-day amount/date/evidence required'using errcode='23514';end if;
 n:=(v->>'amount_minor')::bigint;d:=(v->>'date')::date;perform private.opening_period(cid,d);
 if nullif(v->>'project_id','')is not null and not exists(select 1 from public.projects where company_id=cid and id=(v->>'project_id')::uuid)then raise exception 'Same-Company Project required'using errcode='23514';end if;
 if kind='PREPAY_RECOGNIZE'then
 if v?'parent_id'or coalesce(v->>'service_date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or coalesce(v->>'service_end_date','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then raise exception 'Actual continuous coverage dates required'using errcode='23514';end if;start_day:=(v->>'service_date')::date;end_day:=(v->>'service_end_date')::date;
 if start_day<d or end_day<start_day or end_day-start_day>36600 then raise exception 'Supported non-invented future coverage range required'using errcode='23514';end if;
 if nullif(v->>'corrects_id','')is not null and not exists(select 1 from public.commercial_documents where company_id=cid and id=(v->>'corrects_id')::uuid and commercial_documents.kind=kind and not private.commercial_live(cid,id))then raise exception 'Same-kind reversed correction source required'using errcode='23514';end if;
 bank:=private.commercial_bank(cid,(v->>'treasury_id')::uuid,d,n,true,nullif(v->>'project_id','')::uuid);return jsonb_build_object('amount',n,'lines',jsonb_build_array(private.commercial_line(private.commercial_account(cid,'PREPAYMENT'),n,false,null,nullif(v->>'project_id','')::uuid),private.commercial_line(bank,n,true,null,nullif(v->>'project_id','')::uuid,(v->>'treasury_id')::uuid)));end if;
 if not private.commercial_live(cid,p.id)or p.project_id is distinct from nullif(v->>'project_id','')::uuid or v-array['date','reference','evidence','amount_minor','project_id','parent_id']<>'{}'::jsonb then raise exception 'Live original continuous coverage and Project required'using errcode='23514';end if;
 start_day:=(p.input->>'service_date')::date;end_day:=(p.input->>'service_end_date')::date;
 select coalesce(sum(x.amount_minor),0),max(x.date)into used,last_day from public.commercial_documents x where x.company_id=cid and x.parent_id=p.id and x.kind='PREPAY_AMORTIZE'and private.commercial_live(cid,x.id);
 due:=least(end_day,(date_trunc('month',coalesce(last_day+1,start_day))+interval '1 month'-interval '1 day')::date);expected:=round(p.amount_minor::numeric*(due-start_day+1)/(end_day-start_day+1))::bigint-used;
 if used>=p.amount_minor or d<>due or n<>expected then raise exception 'Next supported actual-day installment is %, due %',expected,due using errcode='23514';end if;
 return jsonb_build_object('amount',n,'lines',jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ACCRUAL_EXPENSE'),n,false,null,p.project_id),private.commercial_line(private.commercial_account(cid,'PREPAYMENT'),n,true,null,p.project_id)));end if;
 return private.recognition_plan_core104(cid,kind,v);end$$;
revoke all on function private.recognition_plan_core104(uuid,text,jsonb),private.recognition_plan(uuid,text,jsonb)from public,anon,authenticated,service_role;
-- Asset sales reuse AR tax/settlement and the existing asset retirement; never a second receipt.
create table private.asset_sale_context(tx bigint not null,company_id uuid not null,asset_id uuid not null,primary key(tx,company_id,asset_id));
revoke all on private.asset_sale_context from public,anon,authenticated,service_role;
create function private.asset_sale_input(cid uuid,v jsonb)returns jsonb language plpgsql set search_path=''as $$declare a public.commercial_documents;p jsonb;begin
 if v-array['date','reference','evidence','amount_minor','parent_id','project_id','party_id','sale_mode','treasury_id','proceeds_minor','vat_minor','vat_rate_bps','tax_evidence','due_date','recognition_confirmed']<>'{}'::jsonb or v->>'sale_mode'not in('CREDIT','CASH')or v->>'sale_mode'is null or v->>'recognition_confirmed'is distinct from 'true'then raise exception 'Supported actual asset sale, Customer, tax and handover facts required'using errcode='23514';end if;
 select *into a from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid and kind='ASSET_CAPITALIZE';
 if a.id is null or not private.commercial_live(cid,a.id)or a.project_id is distinct from nullif(v->>'project_id','')::uuid or(a.amount_minor::text)is distinct from(v->>'amount_minor')or coalesce(v->>'proceeds_minor','')!~'^[0-9]{1,16}$'or(v->>'proceeds_minor')::numeric not between 1 and 9000000000000000 then raise exception 'Live original asset/cost/Project and actual positive selling price required'using errcode='23514';end if;
 p:=jsonb_strip_nulls(jsonb_build_object('date',v->>'date','reference',v->>'reference','evidence',v->>'evidence','party_id',v->>'party_id','project_id',a.project_id,'amount_minor',v->>'proceeds_minor','vat_minor',coalesce(v->>'vat_minor','0'),'vat_rate_bps',v->'vat_rate_bps','tax_evidence',nullif(v->>'tax_evidence',''),'due_date',coalesce(v->>'due_date',v->>'date'),'economic_kind','EARNED_SERVICE','recognition_confirmed',true));if v->>'sale_mode'='CASH'then p:=p||jsonb_build_object('treasury_id',v->>'treasury_id');elsif nullif(v->>'treasury_id','')is not null then raise exception 'Credit asset sale cannot create a cash receipt'using errcode='23514';end if;return p;end$$;
create function private.asset_retirement_lines(cid uuid,v jsonb,net bigint)returns jsonb language plpgsql set search_path=''as $$declare p jsonb;a public.commercial_documents;used bigint;carrying bigint;lines jsonb;begin
 select *into a from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid;
 p:=case when private.cost_credit_total(cid,a.id,'TOTAL')>0 then private.adjusted_asset_plan(cid,'ASSET_DISPOSE',jsonb_strip_nulls(jsonb_build_object('date',v->>'date','reference',v->>'reference','evidence',v->>'evidence','amount_minor',v->>'amount_minor','parent_id',v->>'parent_id','project_id',v->>'project_id','proceeds_minor','0')))else private.recognition_plan_pre104(cid,'ASSET_DISPOSE',jsonb_strip_nulls(jsonb_build_object('date',v->>'date','reference',v->>'reference','evidence',v->>'evidence','amount_minor',v->>'amount_minor','parent_id',v->>'parent_id','project_id',v->>'project_id','proceeds_minor','0')))end;
 select coalesce(sum(amount_minor),0)into used from public.commercial_documents where company_id=cid and parent_id=a.id and kind='ASSET_DEPRECIATE'and private.commercial_live(cid,id);carrying:=a.amount_minor-private.cost_credit_total(cid,a.id,'TOTAL')-used+private.cost_credit_total(cid,a.id,'ACCUM');
 select coalesce(jsonb_agg(x),'[]')into lines from jsonb_array_elements(p->'lines')x where x->>'account_id'<>private.commercial_account(cid,'DISPOSAL_LOSS')::text;
 lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'REVENUE'),net,false,null,a.project_id));
 if net>carrying then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_GAIN'),net-carrying,true,null,a.project_id));elsif net<carrying then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_LOSS'),carrying-net,false,null,a.project_id));end if;return lines;end$$;
alter function private.recognition_plan(uuid,text,jsonb)rename to recognition_plan_days104;
create function private.recognition_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$declare sale jsonb;p jsonb;invoice public.commercial_documents;a public.commercial_documents;begin
 if kind='ASSET_SALE'then sale:=private.asset_sale_input(cid,v);p:=private.customer_plan_legacy104(cid,case when v->>'sale_mode'='CASH'then 'AR_CASH_SALE'else 'AR_INVOICE'end,sale);return jsonb_build_object('amount',v->>'amount_minor','lines',(p->'lines')||private.asset_retirement_lines(cid,v,(v->>'proceeds_minor')::bigint));end if;
 if kind='ASSET_DISPOSE'and nullif(v->>'ar_document_id','')is not null then
 if v-array['date','reference','evidence','amount_minor','parent_id','project_id','ar_document_id','sale_intent_hash']<>'{}'::jsonb then raise exception 'Typed source-linked asset retirement only'using errcode='23514';end if;
 select *into invoice from public.commercial_documents where company_id=cid and id=(v->>'ar_document_id')::uuid;
 select *into a from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid;
 if invoice.id is null or invoice.kind not in('AR_INVOICE','AR_CASH_SALE')or invoice.input->>'economic_kind'<>'ASSET_DISPOSAL'or invoice.input->>'asset_id'<>a.id::text or invoice.project_id is distinct from a.project_id or invoice.date is distinct from(v->>'date')::date or exists(select 1 from public.commercial_documents where company_id=cid and input->>'ar_document_id'=invoice.id::text)then raise exception 'Original same-Company asset sale invoice required; no duplicate retirement'using errcode='23514';end if;
 return jsonb_build_object('amount',a.amount_minor,'lines',private.asset_retirement_lines(cid,v,(invoice.input->>'amount_minor')::bigint));end if;return private.recognition_plan_days104(cid,kind,v);end$$;
-- Only the atomic sale command may ask AR to post its temporary sale revenue.
do $$declare d text;begin d:=pg_get_functiondef('private.customer_plan_pre103(uuid,text,jsonb)'::regprocedure);d:=replace(d,' if kind in(''AR_APPLY'',''AR_REFUND'')then',' if kind in(''AR_INVOICE'',''AR_CASH_SALE'')and v->>''economic_kind''=''ASSET_DISPOSAL''then if not exists(select 1 from private.asset_sale_context where tx=txid_current()and company_id=cid and asset_id=(v->>''asset_id'')::uuid)then raise exception ''Asset sale must post atomically through canonical asset workflow''using errcode=''42501'';end if;return private.customer_plan_legacy104(cid,kind,(v-''asset_id'')||jsonb_build_object(''economic_kind'',''EARNED_SERVICE''));end if; if kind in(''AR_APPLY'',''AR_REFUND'')then');execute d;
 d:=pg_get_functiondef('private.customer_plan(uuid,text,jsonb)'::regprocedure);d:=replace(d,'if kind in(''AR_INVOICE'',''AR_CASH_SALE'')then','if kind in(''AR_INVOICE'',''AR_CASH_SALE'')and v->>''economic_kind''is distinct from ''ASSET_DISPOSAL''then');execute d;end$$;
create function public.command_asset_sale(cid uuid,request_id uuid,input jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
#variable_conflict use_variable
declare actor uuid;h text;old public.commercial_documents;sale jsonb;ar jsonb;result jsonb;disposal jsonb;begin
 actor:=private.operational_finance_actor(cid,'accounting.post');if request_id is null or jsonb_typeof(input)is distinct from 'object'or octet_length(input::text)>16000 then raise exception 'Bounded asset sale and request identity required'using errcode='22023';end if;perform private.serialize_operational_finance(cid,'OPERATIONS');input:=private.normalize_commercial_input(input);h:=encode(extensions.digest(jsonb_build_array(actor,input)::text,'sha256'),'hex');select *into old from public.commercial_documents where company_id=cid and commercial_documents.request_id=command_asset_sale.request_id;
 if old.id is not null then if old.input->>'sale_intent_hash'is distinct from h then raise exception 'Changed asset sale request'using errcode='23505';end if;return jsonb_build_object('id',old.id,'journal_id',old.journal_id,'ar_document_id',old.input->>'ar_document_id','replayed',true);end if;
 perform private.recognition_plan(cid,'ASSET_SALE',input);sale:=private.asset_sale_input(cid,input);sale:=sale||jsonb_build_object('economic_kind','ASSET_DISPOSAL','asset_id',input->>'parent_id');insert into private.asset_sale_context values(txid_current(),cid,(input->>'parent_id')::uuid);
 ar:=public.command_customer_accounting(cid,gen_random_uuid(),case when input->>'sale_mode'='CASH'then 'AR_CASH_SALE'else 'AR_INVOICE'end,sale);
 disposal:=jsonb_strip_nulls(jsonb_build_object('date',input->>'date','reference',input->>'reference','evidence',input->>'evidence','amount_minor',input->>'amount_minor','parent_id',input->>'parent_id','project_id',input->>'project_id','ar_document_id',ar->>'id','sale_intent_hash',h));
 result:=public.command_period_recognition(cid,request_id,'ASSET_DISPOSE',disposal);delete from private.asset_sale_context where tx=txid_current()and company_id=cid and asset_id=(input->>'parent_id')::uuid;return result||jsonb_build_object('ar_document_id',ar->>'id','sale_journal_id',ar->>'journal_id');end$$;
alter function public.command_period_recognition(uuid,uuid,text,jsonb)rename to command_period_recognition_pre104;
create function public.command_period_recognition(cid uuid,request_id uuid,kind text,input jsonb)returns jsonb language plpgsql security definer set search_path=''as $$begin if kind='ASSET_SALE'then return public.command_asset_sale(cid,request_id,input);end if;return public.command_period_recognition_pre104(cid,request_id,kind,input);end$$;
revoke all on function public.command_period_recognition_pre104(uuid,uuid,text,jsonb),public.command_period_recognition(uuid,uuid,text,jsonb),public.command_asset_sale(uuid,uuid,jsonb),private.asset_sale_input(uuid,jsonb),private.asset_retirement_lines(uuid,jsonb,bigint),private.recognition_plan_days104(uuid,text,jsonb),private.recognition_plan(uuid,text,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.command_period_recognition(uuid,uuid,text,jsonb),public.command_asset_sale(uuid,uuid,jsonb)to authenticated;
-- Asset-sale price credits reduce disposal gain / increase loss, not ordinary sales revenue.
create function private.asset_price_credit(cid uuid,v jsonb)returns jsonb language plpgsql set search_path=''as $$declare p public.commercial_documents;d public.commercial_documents;plan jsonb;gain bigint;prior bigint;n bigint;part bigint;lines jsonb;begin
 select *into p from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid;select *into d from public.commercial_documents where company_id=cid and kind='ASSET_DISPOSE'and input->>'ar_document_id'=p.id::text and private.commercial_live(cid,id);
 if d.id is null then raise exception 'Original live asset-sale retirement required'using errcode='23514';end if;
 plan:=private.customer_plan_legacy104(cid,'AR_CREDIT',v);n:=(v->>'amount_minor')::bigint;
 select coalesce(sum(credit_minor-debit_minor),0)into gain from public.journal_lines where company_id=cid and journal_entry_id=d.journal_id and account_id=private.commercial_account(cid,'DISPOSAL_GAIN');
 select coalesce(sum((input->>'amount_minor')::bigint),0)into prior from public.commercial_documents where company_id=cid and parent_id=p.id and kind='AR_CREDIT'and private.construction_live(cid,id);part:=least(greatest(gain-prior,0),n);
 select coalesce(jsonb_agg(x),'[]')into lines from jsonb_array_elements(plan->'lines')x where x->>'account_id'<>private.commercial_account(cid,'REVENUE')::text;
 if part>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_GAIN'),part,false,null,p.project_id));end if;if n>part then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_LOSS'),n-part,false,null,p.project_id));end if;return plan||jsonb_build_object('lines',lines);end$$;
do $$declare d text;begin d:=pg_get_functiondef('private.customer_plan_pre103(uuid,text,jsonb)'::regprocedure);d:=replace(d,' if kind in(''AR_INVOICE'',''AR_CASH_SALE'')and v->>''economic_kind''=''ASSET_DISPOSAL''then',' if kind=''AR_CREDIT''and exists(select 1 from public.commercial_documents where company_id=cid and id=(v->>''parent_id'')::uuid and input->>''economic_kind''=''ASSET_DISPOSAL'')then return private.asset_price_credit(cid,v);end if; if kind in(''AR_INVOICE'',''AR_CASH_SALE'')and v->>''economic_kind''=''ASSET_DISPOSAL''then');execute d;end$$;
-- An AR sale/refund record cannot be silently detached by independently reversing retirement.
do $$declare d text;begin d:=pg_get_functiondef('public.preview_commercial_reversal(uuid,uuid,date,text)'::regprocedure);d:=replace(d,' perform private.opening_period(cid,date);',' if p.kind=''ASSET_DISPOSE''and nullif(p.input->>''ar_document_id'','''')is not null then raise exception ''Asset sale remains an immutable business event; use source-linked price credits or a supported physical-return workflow''using errcode=''23514'';end if;perform private.opening_period(cid,date);');execute d;end$$;
alter table private.asset_sale_context enable row level security;alter table private.asset_sale_context force row level security;
revoke all on function private.asset_price_credit(uuid,jsonb)from public,anon,authenticated,service_role;
-- Preserve qualified parameter references after the canonical command wrapper rename.
do $$declare d text;begin d:=pg_get_functiondef('public.command_period_recognition_pre104(uuid,uuid,text,jsonb)'::regprocedure);d:=replace(d,'command_period_recognition.request_id','command_period_recognition_pre104.request_id');execute d;end$$;
-- Keep source Project dimensions on deposit liabilities and their actual refunds.
do $$declare d text;begin d:=pg_get_functiondef('private.construction_plan_pre104(uuid,text,jsonb)'::regprocedure);d:=replace(d,'''project_id'',case when action=''REFUND''then null else c.project_id end','''project_id'',c.project_id');execute d;
 d:=pg_get_functiondef('private.recognition_plan_pre104(uuid,text,jsonb)'::regprocedure);d:=replace(d,'private.commercial_bank(cid,t,d,n,true)','private.commercial_bank(cid,t,d,n,true,project)');d:=replace(d,'private.commercial_bank(cid,t,d,proceeds,false)','private.commercial_bank(cid,t,d,proceeds,false,project)');execute d;
 d:=pg_get_functiondef('private.customer_plan_pre103(uuid,text,jsonb)'::regprocedure);d:=replace(d,'or project is not null then raise exception ''Actual original deposit refund required''','or project is distinct from adv.project_id then raise exception ''Actual original deposit refund required''');
 d:=replace(d,'n+tax,false)','n+tax,false,project)');d:=replace(d,'n+relief,true)','n+relief,true,project)');
 d:=replace(d,'n,true,(v->>''party_id'')::uuid)','n,true,(v->>''party_id'')::uuid,project)');d:=replace(d,'n,false,adv.party_id)','n,false,adv.party_id,adv.project_id)');
 d:=replace(d,'tax,true))','tax,true,null,project))');d:=replace(d,'relief,false))','relief,false,null,adv.project_id))');execute d;
 d:=pg_get_functiondef('private.construction_plan(uuid,text,jsonb)'::regprocedure);d:=replace(d,'credit-used,true,c.customer_id)','credit-used,true,c.customer_id,c.project_id)');execute d;end$$;
-- Source-linked Supplier price credits must follow capitalized cost, not credit Expense again.
create table public.commercial_cost_credits(
 company_id uuid not null,credit_id uuid not null,asset_id uuid not null,kind text not null check(kind in('ASSET','WIP')),
 amount_minor bigint not null check(amount_minor>0),asset_minor bigint not null check(asset_minor>=0),expense_minor bigint not null check(expense_minor>=0),accum_minor bigint not null check(accum_minor>=0),
 primary key(company_id,credit_id,asset_id),foreign key(company_id,credit_id)references public.supplier_ap_documents(company_id,id),foreign key(company_id,asset_id)references public.commercial_documents(company_id,id));
alter table public.commercial_cost_credits enable row level security;alter table public.commercial_cost_credits force row level security;revoke all on public.commercial_cost_credits from public,anon,authenticated,service_role;grant select on public.commercial_cost_credits to authenticated;
create policy allocated_credit_read on public.commercial_cost_credits for select to authenticated using((public.has_company_role(company_id,'ACCOUNTING_ADMIN')or public.has_company_role(company_id,'ACCOUNTANT')or public.has_company_role(company_id,'MANAGEMENT_VIEWER'))and(kind='ASSET'or public.has_permission(company_id,'payroll.manage')));
create trigger allocated_credit_immutable before update or delete on public.commercial_cost_credits for each row execute function private.financial_evidence_immutable();
create function private.cost_credit_total(cid uuid,asset uuid,component text,cutoff date default 'infinity')returns bigint language sql stable set search_path=''as $$select coalesce(sum(case component when 'ASSET'then a.asset_minor when 'EXPENSE'then a.expense_minor when 'ACCUM'then a.accum_minor else a.amount_minor end),0)::bigint from public.commercial_cost_credits a join public.supplier_ap_documents d on d.company_id=a.company_id and d.id=a.credit_id where a.company_id=cid and a.asset_id=asset and(d.status='POSTED'or d.status='REVERSED'and exists(select 1 from public.journal_entries r where r.company_id=cid and r.id=d.reversal_journal_entry_id and r.posting_date>cutoff))and d.posting_date<=cutoff$$;
create function private.source_credit_total(cid uuid,expense uuid,cutoff date default 'infinity')returns bigint language sql stable set search_path=''as $$select coalesce(sum(net_minor),0)::bigint from public.supplier_ap_documents d where company_id=cid and expense_id=expense and kind='CREDIT_NOTE'and(d.status='POSTED'or d.status='REVERSED'and exists(select 1 from public.journal_entries r where r.company_id=cid and r.id=d.reversal_journal_entry_id and r.posting_date>cutoff))and posting_date<=cutoff$$;
alter function private.supplier_adjustment_plan(uuid,text,jsonb)rename to supplier_adjustment_plan_base104;
create function private.supplier_adjustment_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare plan jsonb;asset public.commercial_documents;disposed public.commercial_documents;src public.expenses;line public.journal_lines;n bigint;cost bigint;used bigint;seq integer;oldcost bigint;newcost bigint;accum bigint;part bigint;released bigint;totalpart bigint;allocated bigint:=0;lines jsonb;allocations jsonb:='[]';is_asset boolean:=false;begin
 plan:=private.supplier_adjustment_plan_base104(cid,kind,v);if kind<>'CREDIT_NOTE'then return plan;end if;
 select *into src from public.expenses where company_id=cid and id=(v->>'expense_id')::uuid;select l.*into line from public.journal_lines l join public.accounts a on a.company_id=l.company_id and a.id=l.account_id where l.company_id=cid and l.journal_entry_id=src.posted_journal_entry_id and a.account_type='EXPENSE'and l.debit_minor>0;
 n:=(plan->>'net_minor')::bigint;cost:=line.debit_minor-private.source_credit_total(cid,src.id);if cost<=0 then raise exception 'Source has no remaining actual acquisition cost'using errcode='23514';end if;
 select coalesce(jsonb_agg(x),'[]')into lines from jsonb_array_elements(plan->'lines')x where x->>'account_id'<>line.account_id::text;
 for asset in select d.*from public.commercial_documents d where d.company_id=cid and((d.kind='ASSET_CAPITALIZE'and d.input->>'source_expense_id'=src.id::text and private.commercial_live(cid,d.id))or(d.kind='CR_WIP_CAPITALIZE'and d.input->>'source_line_id'=line.id::text and private.construction_live(cid,d.id)))order by d.id loop
 if(v->>'date')::date<greatest(asset.date,(select max(x.date)from public.commercial_documents x where x.company_id=cid and x.parent_id=asset.id and private.commercial_live(cid,x.id)and private.construction_live(cid,x.id)))then raise exception 'Cost credit cannot predate existing asset/WIP movements'using errcode='23514';end if;
 if asset.kind='ASSET_CAPITALIZE'then
 is_asset:=true;oldcost:=asset.amount_minor-private.cost_credit_total(cid,asset.id,'TOTAL');newcost:=oldcost-n;if newcost<0 then raise exception 'Credit exceeds actual capitalized cost'using errcode='23514';end if;
 select *into disposed from public.commercial_documents where company_id=cid and parent_id=asset.id and commercial_documents.kind='ASSET_DISPOSE'and private.commercial_live(cid,id);
 if disposed.id is not null then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_GAIN'),n,true,null,asset.project_id));part:=0;accum:=0;
 else
 select coalesce(sum(amount_minor),0)-private.cost_credit_total(cid,asset.id,'ACCUM')into used from public.commercial_documents where company_id=cid and parent_id=asset.id and commercial_documents.kind='ASSET_DEPRECIATE'and private.commercial_live(cid,id);
 accum:=greatest(0,used-greatest(0,newcost-least(coalesce((asset.input->>'residual_minor')::bigint,0),newcost)));part:=n;lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ASSET_COST'),n,true,null,asset.project_id));
 if accum>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ACCUMULATED_DEPRECIATION'),accum,false,null,asset.project_id),private.commercial_line(private.commercial_account(cid,'DEPRECIATION_EXPENSE'),accum,true,null,asset.project_id));end if;end if;
 allocations:=allocations||jsonb_build_array(jsonb_build_object('asset_id',asset.id,'kind','ASSET','amount_minor',n::text,'asset_minor',part::text,'expense_minor','0','accum_minor',accum::text));allocated:=allocated+n;
 else
 if not public.has_permission(cid,'payroll.manage')then raise exception 'Full contract-cost scope required for WIP source credit'using errcode='42501';end if;
 select coalesce(sum(d.amount_minor),0)into released from private.construction_docs(cid,(select contract_id from public.construction_document_links where company_id=cid and document_id=asset.id))d where d.parent_id=asset.id and d.kind in('CR_WIP_RELEASE','CR_WIP_IMPAIR');
 totalpart:=round(n::numeric*(asset.amount_minor-private.cost_credit_total(cid,asset.id,'TOTAL'))/cost);part:=round(n::numeric*(asset.amount_minor-released-private.cost_credit_total(cid,asset.id,'ASSET'))/cost);if totalpart<part or part<0 then raise exception 'WIP source allocation integrity failed'using errcode='23514';end if;
 if part>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'CONSTRUCTION_WIP'),part,true,null,asset.project_id));end if;
 if totalpart>part then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'COGS'),totalpart-part,true,null,asset.project_id));end if;
 if totalpart>0 then allocations:=allocations||jsonb_build_array(jsonb_build_object('asset_id',asset.id,'kind','WIP','amount_minor',totalpart::text,'asset_minor',part::text,'expense_minor',(totalpart-part)::text,'accum_minor','0'));end if;allocated:=allocated+totalpart;end if;
 end loop;
 if allocated=0 then return plan;end if;if allocated>n then raise exception 'Source price credit over-allocation'using errcode='23514';end if;if allocated<n then lines:=lines||jsonb_build_array(private.commercial_line(line.account_id,n-allocated,true,line.party_id,line.project_id));end if;
 return plan||jsonb_build_object('lines',lines,'cost_allocations',allocations);end$$;
do $$declare d text;begin d:=pg_get_functiondef('public.command_supplier_adjustment(uuid,uuid,text,jsonb)'::regprocedure);d:=replace(d,' end if;perform private.complete_financial_command(req.id,j);',' if kind=''CREDIT_NOTE''and plan?''cost_allocations''then insert into public.commercial_cost_credits(company_id,credit_id,asset_id,kind,amount_minor,asset_minor,expense_minor,accum_minor)select cid,did,(x->>''asset_id'')::uuid,x->>''kind'',(x->>''amount_minor'')::bigint,(x->>''asset_minor'')::bigint,(x->>''expense_minor'')::bigint,(x->>''accum_minor'')::bigint from jsonb_array_elements(plan->''cost_allocations'')x;end if;end if;perform private.complete_financial_command(req.id,j);');execute d;end$$;
-- Price changes affect future depreciation and carrying values without rewriting prior journals.
create function private.adjusted_asset_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$
#variable_conflict use_variable
declare p public.commercial_documents;cost bigint;used bigint;months integer;seq integer;residual bigint;due date;n bigint;expected bigint;proceeds bigint;bank uuid;lines jsonb:='[]';project uuid;begin
 select *into p from public.commercial_documents where company_id=cid and id=(v->>'parent_id')::uuid and commercial_documents.kind='ASSET_CAPITALIZE';
 if p.id is null or not private.commercial_live(cid,p.id)or p.date>(v->>'date')::date or p.project_id is distinct from nullif(v->>'project_id','')::uuid or v-array['date','reference','evidence','amount_minor','project_id','parent_id','proceeds_minor','treasury_id']<>'{}'::jsonb or coalesce(length(v->>'reference'),0)not between 1 and 120 or coalesce(length(v->>'evidence'),0)not between 5 and 1000 or(v->>'date')::date>current_date or exists(select 1 from public.commercial_documents where company_id=cid and parent_id=p.id and commercial_documents.kind='ASSET_DISPOSE'and private.commercial_live(cid,id))then raise exception 'Live adjusted asset, consistent Project and actual event required'using errcode='23514';end if;
 perform private.opening_period(cid,(v->>'date')::date);cost:=p.amount_minor-private.cost_credit_total(cid,p.id,'TOTAL');select coalesce(sum(amount_minor),0)-private.cost_credit_total(cid,p.id,'ACCUM'),count(*)into used,seq from public.commercial_documents where company_id=cid and parent_id=p.id and commercial_documents.kind='ASSET_DEPRECIATE'and private.commercial_live(cid,id);
 residual:=least(coalesce((p.input->>'residual_minor')::bigint,0),cost);months:=(p.input->>'life_months')::integer;project:=p.project_id;due:=(date_trunc('month',(p.input->>'service_date')::date)+(seq+1)*interval '1 month'-interval '1 day')::date;n:=(v->>'amount_minor')::bigint;if n is null or n not between 1 and 9000000000000000 then raise exception 'Positive exact asset amount required'using errcode='23514';end if;
 if(v->>'date')::date<(select max(d.posting_date)from public.commercial_cost_credits c join public.supplier_ap_documents d on d.company_id=c.company_id and d.id=c.credit_id where c.company_id=cid and c.asset_id=p.id and d.status='POSTED')then raise exception 'Asset movement cannot predate source price adjustment'using errcode='23514';end if;
 if kind='ASSET_DEPRECIATE'then
 expected:=case when seq>=months then 0 when seq=months-1 then cost-residual-used else(cost-residual-used)/(months-seq)end;
 if v?'treasury_id'or v?'proceeds_minor'or seq>=months or expected<1 or n<>expected or(v->>'date')::date<>due then raise exception 'Next prospective adjusted depreciation is %, due %',expected,due using errcode='23514';end if;
 lines:=jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DEPRECIATION_EXPENSE'),n,false,null,project),private.commercial_line(private.commercial_account(cid,'ACCUMULATED_DEPRECIATION'),n,true,null,project));
 else
 if n<>p.amount_minor or used<cost-residual and seq<months and due<=(v->>'date')::date then raise exception 'Complete supported depreciation before disposing adjusted asset'using errcode='23514';end if;proceeds:=(v->>'proceeds_minor')::bigint;if proceeds is null or proceeds<0 or proceeds>9000000000000000 then raise exception 'Actual disposal proceeds required'using errcode='23514';end if;
 if cost>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ASSET_COST'),cost,true,null,project));end if;if used>0 then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'ACCUMULATED_DEPRECIATION'),used,false,null,project));end if;
 if proceeds>0 then bank:=private.commercial_bank(cid,(v->>'treasury_id')::uuid,(v->>'date')::date,proceeds,false,project);lines:=lines||jsonb_build_array(private.commercial_line(bank,proceeds,false,null,project,(v->>'treasury_id')::uuid));end if;
 if proceeds>cost-used then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_GAIN'),proceeds-cost+used,true,null,project));elsif proceeds<cost-used then lines:=lines||jsonb_build_array(private.commercial_line(private.commercial_account(cid,'DISPOSAL_LOSS'),cost-used-proceeds,false,null,project));end if;
 if jsonb_array_length(lines)<2 then raise exception 'Zero-value physical retirement has no financial journal; retain audited zero carrying value'using errcode='23514';end if;end if;return jsonb_build_object('amount',n,'lines',lines);end$$;
alter function private.recognition_plan(uuid,text,jsonb)rename to recognition_plan_sale104;
create function private.recognition_plan(cid uuid,kind text,v jsonb)returns jsonb language plpgsql set search_path=''as $$begin
 if kind in('ASSET_DEPRECIATE','ASSET_DISPOSE')and not(v?'ar_document_id')and private.cost_credit_total(cid,(v->>'parent_id')::uuid,'TOTAL')>0 then return private.adjusted_asset_plan(cid,kind,v);end if;
 return private.recognition_plan_sale104(cid,kind,v);end$$;
-- Allocated cost is net of actual Supplier price credits; original evidence remains immutable.
do $$declare d text;begin
 d:=pg_get_functiondef('private.construction_plan_pre104(uuid,text,jsonb)'::regprocedure);
 d:=replace(d,'sum(amount_minor),0)into used from public.commercial_documents d','sum(amount_minor-private.cost_credit_total(cid,d.id,''TOTAL'')),0)into used from public.commercial_documents d');
 d:=replace(d,'if used+n>src.debit_minor-src.credit_minor then','if used+n>src.debit_minor-src.credit_minor-private.source_credit_total(cid,je.source_id)then');
 d:=replace(d,'select orig.amount_minor-coalesce(sum(amount_minor),0)into leftover','select orig.amount_minor-private.cost_credit_total(cid,orig.id,''ASSET'')-coalesce(sum(amount_minor),0)into leftover');
 d:=replace(d,'elsif action=''REVERSE''then','elsif action=''REVERSE''then if exists(select 1 from public.commercial_cost_credits a join public.supplier_ap_documents s on s.company_id=a.company_id and s.id=a.credit_id where a.company_id=cid and s.status=''POSTED''and(a.asset_id=(v->>''id'')::uuid or a.asset_id=(select parent_id from public.commercial_documents where company_id=cid and id=(v->>''id'')::uuid))and s.created_at>(select created_at from public.commercial_documents where company_id=cid and id=(v->>''id'')::uuid))then raise exception ''Reverse dependent Supplier cost credits before WIP corrections''using errcode=''23514'';end if;');execute d;
 -- A new WIP allocation cannot reuse an already capitalized fixed-asset source.
 d:=pg_get_functiondef('private.construction_plan_pre104(uuid,text,jsonb)'::regprocedure);d:=replace(d,'if action=''CAPITALIZE_WIP''then','if action=''CAPITALIZE_WIP''then if exists(select 1 from public.commercial_documents a where a.company_id=cid and a.kind=''ASSET_CAPITALIZE''and a.input->>''source_expense_id''=je.source_id::text and private.commercial_live(cid,a.id))then raise exception ''Source already capitalized as a fixed asset''using errcode=''23514'';end if;');execute d;
 d:=pg_get_functiondef('private.construction_balance(uuid,uuid,date)'::regprocedure);d:=replace(d,'coalesce(sum(amount_minor)filter(where kind in(''CR_WIP_CAPITALIZE'',''CR_WIP_OPENING'')),0)','coalesce(sum(amount_minor-private.cost_credit_total(cid,id,''ASSET'',cutoff))filter(where kind in(''CR_WIP_CAPITALIZE'',''CR_WIP_OPENING'')),0)');execute d;
 d:=pg_get_functiondef('public.preview_commercial_reversal(uuid,uuid,date,text)'::regprocedure);d:=replace(d,' perform private.opening_period(cid,date);',' if exists(select 1 from public.commercial_cost_credits a join public.supplier_ap_documents s on s.company_id=a.company_id and s.id=a.credit_id where a.company_id=cid and s.status=''POSTED''and a.asset_id=case when p.kind=''ASSET_CAPITALIZE''then p.id else p.parent_id end and(p.kind=''ASSET_CAPITALIZE''or s.created_at>p.created_at))then raise exception ''Reverse dependent Supplier cost credits before asset corrections''using errcode=''23514'';end if;perform private.opening_period(cid,date);');execute d;
 d:=pg_get_functiondef('public.command_supplier_adjustment(uuid,uuid,text,jsonb)'::regprocedure);d:=replace(d,'j:=private.reverse_journal(original.posted_journal_entry_id',
 'if exists(select 1 from public.commercial_cost_credits a join public.commercial_documents x on x.company_id=a.company_id and (x.parent_id=a.asset_id or x.id=a.asset_id) where a.company_id=cid and a.credit_id=original.id and x.created_at>(select created_at from public.supplier_ap_documents where company_id=cid and id=original.id)and private.commercial_live(cid,x.id)and private.construction_live(cid,x.id))or exists(select 1 from public.commercial_documents x where x.company_id=cid and (x.input->>''source_expense_id''=original.expense_id::text or x.input->>''source_line_id''in(select l.id::text from public.journal_lines l join public.expenses e on e.company_id=l.company_id and e.posted_journal_entry_id=l.journal_entry_id where e.company_id=cid and e.id=original.expense_id))and x.created_at>(select created_at from public.supplier_ap_documents where company_id=cid and id=original.id)and private.commercial_live(cid,x.id)and private.construction_live(cid,x.id))then raise exception ''Reverse later source capitalization/depreciation/disposal/WIP dependencies before Supplier credit correction''using errcode=''23514'';end if;j:=private.reverse_journal(original.posted_journal_entry_id');execute d;
end$$;
-- Current and historical registers reconcile carrying cost after audited Supplier credits.
do $$declare d text;begin d:=pg_get_functiondef('public.read_period_recognition(uuid,date)'::regprocedure);
 d:=replace(d,'''effective'',private.commercial_live(cid,x.id,as_of),','''current_cost_minor'',(x.amount_minor-case when x.kind=''ASSET_CAPITALIZE''then private.cost_credit_total(cid,x.id,''TOTAL'',as_of)else 0 end)::text,''effective'',private.commercial_live(cid,x.id,as_of),');
 d:=replace(d,'else x.amount_minor-coalesce','else x.amount_minor-case when x.kind=''ASSET_CAPITALIZE''then private.cost_credit_total(cid,x.id,''TOTAL'',as_of)-private.cost_credit_total(cid,x.id,''ACCUM'',as_of)else 0 end-coalesce');execute d;
 d:=pg_get_functiondef('public.read_construction(uuid,uuid,date)'::regprocedure);d:=replace(d,'d.amount_minor>coalesce','d.amount_minor-private.cost_credit_total(cid,d.id,''ASSET'',as_of)>coalesce');execute d;
end$$;
revoke all on function private.cost_credit_total(uuid,uuid,text,date),private.source_credit_total(uuid,uuid,date),private.supplier_adjustment_plan_base104(uuid,text,jsonb),private.supplier_adjustment_plan(uuid,text,jsonb),private.adjusted_asset_plan(uuid,text,jsonb),private.recognition_plan_sale104(uuid,text,jsonb),private.recognition_plan(uuid,text,jsonb)from public,anon,authenticated,service_role;

do $$declare d text;begin d:=pg_get_functiondef('public.read_commercial_workspace(uuid)'::regprocedure);d:=replace(d,'''asset_sources'',','''customers'',coalesce((select jsonb_agg(jsonb_build_object(''id'',p.id,''name'',p.name))from public.customer_accounts c join public.parties p on p.company_id=c.company_id and p.id=c.party_id where c.company_id=cid),''[]''::jsonb),''asset_sources'',');execute d;end$$;
-- Cash-flow classification follows actual asset documents, not the generic AR/AP source label.
create function public.read_asset_cash_classification(cid uuid,cutoff date)returns jsonb language plpgsql stable security definer set search_path=''as $$begin
 if auth.uid()is null or not(public.has_company_role(cid,'ACCOUNTING_ADMIN')or public.has_company_role(cid,'ACCOUNTANT'))or not public.has_permission(cid,'payroll.manage')then raise exception 'Complete authorized cash-flow scope required'using errcode='42501';end if;
 if cutoff is null or cutoff>current_date then raise exception 'Actual cutoff required'using errcode='22023';end if;
 return(select coalesce(jsonb_object_agg(journal_id,jsonb_build_object('investing',investing::text,'total',total::text)),'{}')from(
 select d.journal_id,1::bigint investing,1::bigint total from public.commercial_documents d left join public.commercial_documents p on p.company_id=d.company_id and p.id=d.parent_id left join public.commercial_documents g on g.company_id=p.company_id and g.id=p.parent_id where d.company_id=cid and d.date<=cutoff and d.kind in('AR_CASH_SALE','AR_RECEIPT','AR_REFUND')and(d.input->>'economic_kind'='ASSET_DISPOSAL'or p.input->>'economic_kind'='ASSET_DISPOSAL'or g.input->>'economic_kind'='ASSET_DISPOSAL')
 union all select e.posted_journal_entry_id,1,1 from public.expenses e where e.company_id=cid and e.funding_mode in('TREASURY','CUSTODIAN')and exists(select 1 from public.commercial_documents a where a.company_id=cid and a.kind='ASSET_CAPITALIZE'and a.input->>'source_expense_id'=e.id::text and a.date<=cutoff and private.commercial_live(cid,a.id,cutoff))
 union all select p.posted_journal_entry_id,sum(al.allocated_amount_minor)filter(where exists(select 1 from public.commercial_documents a where a.company_id=cid and a.kind='ASSET_CAPITALIZE'and a.input->>'source_expense_id'=al.expense_id::text and a.date<=cutoff and private.commercial_live(cid,a.id,cutoff)))::bigint,p.total_amount_minor from public.supplier_payments p join public.supplier_payment_allocations al on al.company_id=p.company_id and al.supplier_payment_id=p.id where p.company_id=cid and p.payment_date<=cutoff group by p.id having count(*)filter(where exists(select 1 from public.commercial_documents a where a.company_id=cid and a.kind='ASSET_CAPITALIZE'and a.input->>'source_expense_id'=al.expense_id::text and a.date<=cutoff and private.commercial_live(cid,a.id,cutoff)))>0
 union all select r.journal_id,1,1 from public.supplier_credit_refunds r join public.supplier_ap_documents c on c.company_id=r.company_id and c.id=r.credit_note_id where r.company_id=cid and r.date<=cutoff and exists(select 1 from public.commercial_documents a where a.company_id=cid and a.kind='ASSET_CAPITALIZE'and a.input->>'source_expense_id'=c.expense_id::text and a.date<=cutoff and private.commercial_live(cid,a.id,cutoff))
 )x);end$$;
revoke all on function public.read_asset_cash_classification(uuid,date)from public,anon,authenticated,service_role;grant execute on function public.read_asset_cash_classification(uuid,date)to authenticated;

-- One corrected replacement per reversed business document; further corrections follow that replacement.
create unique index commercial_corrected_replacement_once on public.commercial_documents(company_id,(input->>'corrects_id'))where input?'corrects_id';
do $$declare d text;begin d:=pg_get_functiondef('private.construction_plan_pre104(uuid,text,jsonb)'::regprocedure);d:=replace(d,'if used+n>src.debit_minor-src.credit_minor-private.source_credit_total(cid,je.source_id)then','if exists(select 1 from public.supplier_ap_documents ac where ac.company_id=cid and ac.expense_id=je.source_id and ac.kind=''CREDIT_NOTE''and ac.status=''POSTED''and ac.posting_date>(v->>''date'')::date)or used+n>src.debit_minor-src.credit_minor-private.source_credit_total(cid,je.source_id)then');execute d;end$$;
